<?php require_once 'auth_check.php';require_once '../koneksi.php';require_once 'app_helpers.php';wajib_role(['ADMIN']);$f=mysqli_query($koneksi,"SELECT id_fakultas,nama_fakultas FROM fakultas ORDER BY nama_fakultas");$d=['kode_program_studi'=>'','nama_program_studi'=>'','id_fakultas'=>'','jenjang'=>'S1','status_aktif'=>'Aktif'];$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_verify();foreach($d as $k=>$v)$d[$k]=trim($_POST[$k]??$v);$d['id_fakultas']=(int)$d['id_fakultas'];if(!$d['kode_program_studi']||!$d['nama_program_studi']||!$d['id_fakultas'])$error='Kode, nama, dan fakultas wajib diisi.';if(!$error){$st=mysqli_prepare($koneksi,"INSERT INTO program_studi(id_fakultas,kode_program_studi,nama_program_studi,jenjang,status_aktif) VALUES(?,?,?,?,?)");mysqli_stmt_bind_param($st,'issss',$d['id_fakultas'],$d['kode_program_studi'],$d['nama_program_studi'],$d['jenjang'],$d['status_aktif']);if(mysqli_stmt_execute($st)){audit_log($koneksi,(int)$_SESSION['id_pengguna'],'program_studi',(string)mysqli_insert_id($koneksi),'INSERT',null,$d);flash('success','Program Studi berhasil ditambahkan.');redirect_to('prodi.php');}$error='Gagal menyimpan.';mysqli_stmt_close($st);}}?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tambah Program Studi</title><link rel="stylesheet" href="style.css"></head><body class="app-body"><?php include 'topbar.php';include 'sideleftbar.php';?><main class="main-content"><div class="page-heading"><span class="eyebrow">MASTER DATA</span><h1>Tambah Program Studi</h1></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="dashboard-panel form-panel"><form method="post"><div class="form-grid"><div class="form-group"><label>Kode</label><input name="kode_program_studi" required value="<?=e($d['kode_program_studi'])?>"></div><div class="form-group"><label>Nama Program Studi</label><input name="nama_program_studi" required value="<?=e($d['nama_program_studi'])?>"></div><div class="form-group"><label>Fakultas</label><select name="id_fakultas" required><?php while($x=mysqli_fetch_assoc($f)):?><option value="<?=$x['id_fakultas']?>" <?=$d['id_fakultas']==$x['id_fakultas']?'selected':''?>><?=e($x['nama_fakultas'])?></option><?php endwhile;?></select></div><div class="form-group"><label>Jenjang</label><select name="jenjang"><?php foreach(['D3','D4','S1','S2','S3'] as $x):?><option <?=$d['jenjang']===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select></div><div class="form-group"><label>Status</label><select name="status_aktif"><option <?=$d['status_aktif']==='Aktif'?'selected':''?>>Aktif</option><option <?=$d['status_aktif']==='Tidak Aktif'?'selected':''?>>Tidak Aktif</option></select></div></div><div class="form-actions"><a class="btn btn-outline" href="prodi.php">Batal</a><button class="btn btn-primary">Simpan</button></div><?=csrf_field()?></form></div></main><script src="script.js"></script></body></html>